import numpy as np
import matplotlib.pyplot as plt
import scipy.integrate as integrate
import math as m 

D = np.arange(0.1,15,0.01)
rho = 1
lamb = 1
alpha = 3
N_0 = 1e6 

t = np.arange(0,600,1)
# f = lambda D :  1e6*D**(3+1)*np.exp(-1*D)
# n_D = np.zeros(len(t))
# n_D[0] = integrate.quad(f, 0.1, 15)[0]
M_3 = np.zeros(len(t))
M_3[0] = N_0*m.gamma(3+3+1)/1**(3+3+1)
M_2 = np.zeros(len(t))
M_2[0] = N_0*m.gamma(2+3+1)/1**(2+3+1)



for i in range(len(t)-1):
    
    f = lambda D :  N_0*D**alpha*np.exp(-lamb*D)
    M_0 = integrate.quad(f, 0.1, 15)[0]
    
    f1 = lambda D :  N_0*D**(alpha+1)*np.exp(-lamb*D)
    dQ_dt = 2*np.pi*0.01*integrate.quad(f1, 0.1, 15)[0]
    dM3_dt = 6*dQ_dt/(np.pi*rho)
    
    M_3[i+1] = M_3[i] + dM3_dt*1
    
    f2 = lambda D :  N_0*D**(alpha)*np.exp(-lamb*D)
    dM2_dt = 8/rho*0.01*integrate.quad(f2, 0.1, 15)[0]
    M_2[i+1] = M_2[i] + dM2_dt*1
    
    q = M_0*M_3[i+1]**2/M_2[i+1]**3
    alpha = (6-3*q+np.sqrt(q*(q+8)))/(2*(q-1))
    lamb = ((M_0*m.gamma(alpha+4))/(M_3[i+1]*m.gamma(alpha+1)))**(1/3)
    N_0 = M_0*lamb**(alpha+1)/m.gamma(alpha+1)

    if i == 299:
        n_D_5min = N_0*D**alpha*np.exp(-lamb*D)
    if i == 598:
        n_D_10min = N_0*D**alpha*np.exp(-lamb*D)


n_D_0min = 1e6*D**3*np.exp(-D)

plt.figure(figsize=(8,5))
plt.grid()
plt.plot(D,n_D_0min)
plt.plot(D,n_D_5min)
plt.plot(D,n_D_10min)
plt.legend(['0 min','5 mins','10 mins'])
plt.title('Number density function \n under condensation growth',fontsize=17)
plt.xlabel('Diameter [mm]',fontsize=13)
plt.ylabel('n(D) [$m^{-3}$$μm^{-1}$]',fontsize=13)
plt.xlim(0,15)
plt.savefig('number density function.png',dpi=300)
plt.show()
plt.close()

t = t/60
plt.grid()
plt.plot(t,M_2)
plt.xlabel('Time [min]',fontsize=12)
plt.ylabel('Moment [$μm^{3}$$m^{-3}$]',fontsize=12)
plt.title('Evolution of $M_{2}$ with time',fontsize=15)
plt.savefig('M2',dpi=300)
plt.xlim(0,10)
plt.ylim(1e8,4.5e8)
plt.savefig('M2.png',dpi=300)
plt.show()
plt.close()


plt.grid()
plt.plot(t,M_3)
plt.xlabel('Time [min]',fontsize=12)
plt.ylabel('Moment [$μm^{3}$$m^{-3}$]',fontsize=12)
plt.title('Evolution of $M_{3}$ with time',fontsize=15)
plt.savefig('M3',dpi=300)
plt.xlim(0,10)
plt.ylim(0.5e9,3.5e9)
plt.savefig('M3.png',dpi=300)
plt.show()
plt.close()


